"""Original CRAFT publication Appendix A, not vectors generated by this code."""

import pytest

from claasp.primitives import Craft


@pytest.mark.parametrize(
    "plaintext,key,tweak,ciphertext",
    [
        (0, 0, 0, 0xF630538883063100),
        (0x0123456789ABCDEF, 0, 0x0123456789ABCDEF, 0x2DB468477C1D6C59),
        (0xFEDCBA9876543210, 0x0123456789ABCDEFFEDCBA9876543210, 0, 0x9EDA9131B9155B51),
        (
            0x5734F006D8D88A3E,
            0x27A6781A43F364BC916708D5FBB5AEFE,
            0x54CD94FFD0670A58,
            0xA17D6BD4BEEB996F,
        ),
    ],
)
def test_original_craft_full_cipher_test_vectors(plaintext, key, tweak, ciphertext):
    assert Craft().evaluate(plaintext=plaintext, key=key, tweak=tweak) == ciphertext


@pytest.mark.parametrize(
    "rounds,result",
    [
        (1, 0xCCCCCCCCCAACCCCC),
        (8, 0x28E562EF6C580A8C),
        (14, 0xA9548DEF40B463EE),
        (31, 0x4436E78883063100),
    ],
)
def test_original_intermediate_round_vectors(rounds, result):
    assert Craft(number_of_rounds=rounds).evaluate(plaintext=0, key=0, tweak=0) == result


def test_adjacent_absolute_windows_compose_including_special_final_round():
    first = Craft(number_of_rounds=8).evaluate(plaintext=0x1234, key=0x987654321, tweak=0xA5)
    whole = Craft().evaluate(plaintext=0x1234, key=0x987654321, tweak=0xA5)
    rest = Craft(number_of_rounds=24, round_offset=8).evaluate(
        plaintext=first, key=0x987654321, tweak=0xA5
    )
    assert rest == whole


@pytest.mark.parametrize(
    "kwargs",
    [
        {"number_of_rounds": 0},
        {"number_of_rounds": 33},
        {"round_offset": -1},
        {"number_of_rounds": 2, "round_offset": 31},
        {"number_of_rounds": True},
    ],
)
def test_invalid_windows(kwargs):
    with pytest.raises(ValueError):
        Craft(**kwargs)
